from math import comb

results = {}
for n in range(3, 8):
    f_Kn = comb(n, 3)
    g_Kn = comb(n, 4)

    # Calculate g(K_n)^3 / f(K_n)^4
    if f_Kn == 0:
        ratio = None # Should not happen for n >= 3
    else:
        ratio = (g_Kn**3) / (f_Kn**4)

    results[n] = {
        "f(K_n)": f_Kn,
        "g(K_n)": g_Kn,
        "Ratio": ratio
    }

print(results)

